import {useMemo,useState} from 'react';
import {FlatList,Modal,Pressable,StyleSheet,Text,View} from '@/platform/react-native';
import {Ionicons} from '@/platform/icons';
import {useAppTheme} from './UI';

const pad=(n:number)=>String(n).padStart(2,'0');
export const displayDate=(iso?:string)=>{if(!iso)return'';const [y,m,d]=iso.slice(0,10).split('-');return y&&m&&d?`${d}-${m}-${y}`:iso};

export function DateField({value,onChange,placeholder='DD-MM-YYYY',maximumDate,minimumDate,showIcon=true}:{value:string;onChange:(iso:string)=>void;placeholder?:string;maximumDate?:Date;minimumDate?:Date;showIcon?:boolean}){
 const{palette}=useAppTheme(),fallback=maximumDate||new Date();
 const initial=useMemo(()=>{const parsed=value?new Date(`${value.slice(0,10)}T00:00:00`):fallback;return Number.isNaN(parsed.getTime())?fallback:parsed},[value]);
 const[open,setOpen]=useState(false),[cursor,setCursor]=useState(new Date(initial.getFullYear(),initial.getMonth(),1)),[menu,setMenu]=useState<'month'|'year'|null>(null);
 const months=useMemo(()=>Array.from({length:12},(_,i)=>new Date(2000,i,1).toLocaleDateString(undefined,{month:'long'})),[]),minYear=minimumDate?.getFullYear()??1900,maxYear=maximumDate?.getFullYear()??new Date().getFullYear()+20,years=useMemo(()=>Array.from({length:maxYear-minYear+1},(_,i)=>String(maxYear-i)),[minYear,maxYear]);
 const days=new Date(cursor.getFullYear(),cursor.getMonth()+1,0).getDate(),offset=new Date(cursor.getFullYear(),cursor.getMonth(),1).getDay(),cells=[...Array(offset).fill(null),...Array.from({length:days},(_,i)=>i+1)];
 const select=(day:number)=>{const date=new Date(cursor.getFullYear(),cursor.getMonth(),day);if(maximumDate&&date>maximumDate)return;if(minimumDate&&date<minimumDate)return;onChange(`${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(day)}`);setOpen(false)};
 return <><Pressable accessibilityRole="button" accessibilityLabel="Select date" onPress={()=>setOpen(true)} style={[s.field,{borderColor:palette.border,backgroundColor:palette.surface}]}><Text numberOfLines={1} style={[s.fieldText,{color:value?palette.text:palette.muted}]}>{value?displayDate(value):placeholder}</Text>{showIcon?<Ionicons name="calendar-outline" size={21} color={palette.primary}/>:null}</Pressable><Modal visible={open} transparent animationType="fade" onRequestClose={()=>setOpen(false)}><View style={s.backdrop}><View style={[s.calendar,{backgroundColor:palette.background}]}>{menu?<><View style={s.head}><Text style={[s.title,{color:palette.text}]}>Select {menu}</Text><Pressable onPress={()=>setMenu(null)} style={s.touch}><Ionicons name="close" size={25} color={palette.text}/></Pressable></View><FlatList style={s.list} data={menu==='month'?months:years} keyExtractor={x=>String(x)} renderItem={({item,index})=><Pressable onPress={()=>{setCursor(new Date(menu==='year'?Number(item):cursor.getFullYear(),menu==='month'?index:cursor.getMonth(),1));setMenu(null)}} style={[s.option,{borderBottomColor:palette.border}]}><Text style={{fontSize:17,fontWeight:'700',color:palette.text}}>{item}</Text></Pressable>}/></>:<><View style={s.head}><Pressable onPress={()=>setCursor(new Date(cursor.getFullYear(),cursor.getMonth()-1,1))} style={s.touch}><Ionicons name="chevron-back" size={24} color={palette.text}/></Pressable><View style={s.selectors}><Pressable onPress={()=>setMenu('month')} style={[s.selector,{borderColor:palette.border}]}><Text style={[s.title,{color:palette.text}]}>{months[cursor.getMonth()]}</Text><Ionicons name="chevron-down" size={15} color={palette.primary}/></Pressable><Pressable onPress={()=>setMenu('year')} style={[s.selector,{borderColor:palette.border}]}><Text style={[s.title,{color:palette.text}]}>{cursor.getFullYear()}</Text><Ionicons name="chevron-down" size={15} color={palette.primary}/></Pressable></View><Pressable onPress={()=>setCursor(new Date(cursor.getFullYear(),cursor.getMonth()+1,1))} style={s.touch}><Ionicons name="chevron-forward" size={24} color={palette.text}/></Pressable></View><View style={s.grid}>{['S','M','T','W','T','F','S'].map((x,i)=><Text key={x+i} style={[s.cell,s.weekday,{color:palette.muted}]}>{x}</Text>)}{cells.map((day,i)=>{if(!day)return <View key={i} style={s.cell}/>;const date=new Date(cursor.getFullYear(),cursor.getMonth(),day),disabled=!!((maximumDate&&date>maximumDate)||(minimumDate&&date<minimumDate)),selected=value===`${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(day)}`;return <Pressable key={i} disabled={disabled} onPress={()=>select(day)} style={[s.cell,selected&&{backgroundColor:palette.primary,borderRadius:20}]}><Text style={{fontSize:15,fontWeight:'700',color:selected?'#fff':disabled?palette.border:palette.text}}>{day}</Text></Pressable>})}</View><Pressable onPress={()=>setOpen(false)} style={[s.cancel,{borderColor:palette.primary}]}><Text style={{color:palette.primary,fontWeight:'900'}}>Cancel</Text></Pressable></>}</View></View></Modal></>;
}

const s=StyleSheet.create({field:{minHeight:54,borderWidth:1.5,borderRadius:13,paddingHorizontal:16,flexDirection:'row',alignItems:'center',justifyContent:'space-between',marginBottom:12},fieldText:{flex:1,fontSize:16,fontWeight:'600'},backdrop:{flex:1,backgroundColor:'rgba(15,31,68,.38)',alignItems:'center',justifyContent:'center',padding:20},calendar:{width:'100%',maxWidth:400,borderRadius:20,padding:18,elevation:8},head:{flexDirection:'row',alignItems:'center',justifyContent:'space-between',marginBottom:15},touch:{width:42,height:42,alignItems:'center',justifyContent:'center'},selectors:{flexDirection:'row',gap:7,flexShrink:1},selector:{minHeight:40,borderWidth:1,borderRadius:9,paddingHorizontal:9,flexDirection:'row',alignItems:'center',gap:4},title:{fontSize:16,fontWeight:'900'},grid:{flexDirection:'row',flexWrap:'wrap'},cell:{width:'14.2857%',height:41,alignItems:'center',justifyContent:'center'},weekday:{fontSize:12,fontWeight:'900'},cancel:{minHeight:46,borderWidth:1,borderRadius:12,alignItems:'center',justifyContent:'center',marginTop:12},list:{maxHeight:390},option:{minHeight:49,borderBottomWidth:1,alignItems:'center',justifyContent:'center'}});
